draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // draw a fruit (apple) with a benefits text
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('1600 calories', W/2 + 120, H/2 - 20);

  // animate the character and fruit with Math.sin(t)
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(0, 50);
  ctx.stroke();
  ctx.restore();

  // animate the benefits text
  ctx.save();
  ctx.translate(W/2 + 100, H/2);
  ctx.rotate(Math.cos(t));
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Nutrition Health', W/2 + 120, H/2 - 40);
  ctx.restore();

  ctx.restore();
}
